import numpy as np, itertools
from scipy.optimize import least_squares
t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
TF={'t^a':lambda a: t**a,'exp(-a t)':lambda a: np.exp(-a*t),'cos(a t)':lambda a: np.cos(a*t),'sin(a t)':lambda a: np.sin(a*t),'log(t)*t^a':lambda a: np.log(t)*t**a,'t^a*exp(-t)':lambda a: t**a*np.exp(-t)}
AF={'A^b':lambda b: A**b,'exp(-bA)':lambda b: np.exp(-b*A),'A/(1+bA)':lambda b: A/(1+b*A),'sin(bA)':lambda b: np.sin(b*A),'cos(bA)':lambda b: np.cos(b*A),'cos(b sqrtA)':lambda b: np.cos(b*np.sqrt(A)),'log(A)':lambda b: np.log(A)*b,'exp(-bA^2)':lambda b: np.exp(-b*A*A)}
def build(nl,tf,af):
    return np.column_stack([1/t,(A/(1+nl[0]*A))*t**3,np.sin(nl[1]*np.sqrt(A))*t**1.5, TF[tf](nl[2])*AF[af](nl[3])])
def rr(nl,tf,af):
    B=build(nl,tf,af)
    c,*_=np.linalg.lstsq(B,y,rcond=None)
    return np.nan_to_num(y-B@c,nan=1e3,posinf=1e3,neginf=-1e3)
results=[]
for tf,af in itertools.product(TF,AF):
    best=None
    for s in range(6):
        rng=np.random.default_rng(s)
        p0=[rng.uniform(-0.5,1),rng.uniform(0.5,3),rng.uniform(-1,2),rng.uniform(-1,2)]
        try:
            with np.errstate(all='ignore'):
                r=least_squares(rr,p0,args=(tf,af),max_nfev=60)
            if best is None or r.cost<best.cost: best=r
        except Exception: pass
    if best is None: continue
    results.append((np.var(best.fun)/np.var(y), tf, af, np.round(best.x,3).tolist()))
for r_ in sorted(results)[:8]: print(r_)
